import { path, FileSystem } from '@servicenow/sdk-build-core'
import type { Project } from '../project'
import { isWebWorker, hasModuleLoader } from './environment'
import { createSandboxedRegisterExplicitId } from './register-explicit-id'
import type { LazyCredential } from '../credentials'

export function projectHasScript(project: Project, scriptName: string): boolean {
    const fs = project.getFileSystem()
    const config = project.getConfig()
    const scriptPath = config.scripts?.[scriptName]

    if (scriptPath) {
        const absoluteScriptPath = project.resolvePath(scriptPath)
        if (FileSystem.existsSync(fs, absoluteScriptPath)) {
            return true
        }
    }

    // Fallback: check for now.scriptName.mjs
    const fallbackPath = project.resolvePath(`now.${scriptName}.mjs`)
    if (FileSystem.existsSync(fs, fallbackPath)) {
        return true
    }

    return false
}

export async function runScriptInProject({
    scriptName,
    project,
    credential,
    throwIfNotFound = false,
}: {
    scriptName: string
    project: Project
    credential?: LazyCredential | undefined
    throwIfNotFound?: boolean
}): Promise<void> {
    const rootDir = project.getRootDir()
    const fs = project.getFileSystem()
    const config = project.getConfig()
    const logger = project.getLogger()
    const registerExplicitId = createSandboxedRegisterExplicitId(project)

    let absoluteScriptPath: string | null = null
    const scriptPath = config.scripts?.[scriptName]

    // If script is explicitly defined in config, use that path (takes precedence)
    if (scriptPath) {
        const configPath = project.resolvePath(scriptPath)
        if (!FileSystem.existsSync(fs, configPath)) {
            if (throwIfNotFound) {
                throw Error(`Script "${scriptName}" defined in config at "${scriptPath}" not found at ${configPath}.`)
            }
            return
        }
        absoluteScriptPath = configPath
    } else {
        // Only check fallback if script NOT defined in config
        const fallbackPath = project.resolvePath(`now.${scriptName}.mjs`)
        if (FileSystem.existsSync(fs, fallbackPath)) {
            absoluteScriptPath = fallbackPath
        } else {
            if (throwIfNotFound) {
                throw Error(
                    `No script defined for "${scriptName}". Please add it to scripts in now.config.json or create now.${scriptName}.mjs.`
                )
            }
            return
        }
    }

    logger.info(`Running script "${scriptName}" from ${absoluteScriptPath}`)
    let scriptResults = null
    if (isWebWorker && hasModuleLoader()) {
        scriptResults = await require(absoluteScriptPath)
    } else {
        const webpackWillIgnoreThisIhateYouWebpack = (p: string) => `file://${p}`
        scriptResults = await import(webpackWillIgnoreThisIhateYouWebpack(absoluteScriptPath))
    }
    const taskFns = Array.isArray(scriptResults.default) ? scriptResults.default : [scriptResults.default]
    for (const taskFn of taskFns) {
        if (typeof taskFn === 'function') {
            await taskFn({ rootDir, config, fs, path, logger, registerExplicitId, credential })
        } else {
            logger.warn(
                `Skipping non-function task in script "${scriptName}": ${taskFn?.toString()} . Please export a function or an array of functions.`
            )
        }
    }
    logger.info(`Script "${scriptName}" completed successfully`)
}
